const API = "https://api.toko.contoh";
const ambilJson = async (path) => (await fetch(API + path)).json();
const rp = (n) => "Rp" + n.toLocaleString("id-ID");
async function buatDashboard(userId) {
  const [pengguna, pesanan] = await Promise.___([
    ambilJson(`/users/${userId}`),
    ambilJson(`/orders?userId=${userId}`),
  ]);
  console.log(`${pengguna.name} (${pengguna.city})`);
  if (pesanan.length === 0) return console.log("Belum ada pesanan");
  const produk = await Promise.all(pesanan.___((o) => ambilJson(`/products/${o.productId}`)));
  let total = 0;
  pesanan.forEach((o, i) => {
    const subtotal = produk[i].price * o.qty;
    total += subtotal;
    console.log(`- ${produk[i].name} x${o.qty} = ${rp(subtotal)}`);
  });
  console.log(`Total: ${rp(total)}`);
}
await buatDashboard("U1");
await buatDashboard("U3");

